struct component { const char *name; void *h; int (*init)(void); void (*fini)(void); };

void *h = dlopen(cfg->path, RTLD_NOW | RTLD_LOCAL);
if (!h) die("dlopen %s: %s", cfg->path, dlerror());
dlerror();                                  /* clear prior error state */
int (*init)(void) = dlsym(h, "component_init");
if (!init || dlerror()) die("no component_init in %s", cfg->path);
if (init() != 0) { dlclose(h); die("init failed"); }
/* unlink: fini(); dlclose(h);  in reverse dependency order */
